with d as (select date, close, high, low, max(close) over (order by date) pk, max(high) over (order by date) pkh from candles_1d where product='BTC-USD' and is_complete and date>='2026-01-01'),
x as (select date, close, pk, (close/pk-1)*100 dd, (low/pkh-1)*100 ddh from d)
select * from x order by dd limit 3;
